// "Mon imagier": the chapters and words of her picture dictionary, with where each word's drawing
// and label sit on the book's pages. Only words and page coordinates are here. The drawings come
// from her own copy of the book, which Bonbon reads on her device (see lib/imagier-book.ts).
// words.json and meta.json are generated by the extraction tools from the checked chapter files.
import type { Box, PaletteKey, Spot } from '../../types';
import { slugify } from '../../lib/ids';
import meta from './meta.json';

export type ImagierKind = 'noun' | 'verb' | 'adjective' | 'number' | 'color' | 'preposition' | 'phrase' | 'other';

export interface ImagierChapter {
  num: number;
  title: string;
  en: string;
  /** PDF pages (1-based) of the chapter's spread. */
  pages: number[];
  /** Words in the chapter. */
  count: number;
  emoji: string;
  color: PaletteKey;
}

export interface ImagierWord {
  /** Card id, stable across versions: "i08-le-batiment". */
  id: string;
  chapter: number;
  fr: string;
  en: string;
  kind: ImagierKind;
  /** Nouns: "mf" when one form serves both (l'élève). */
  g?: 'm' | 'f' | 'mf';
  plural?: boolean;
  emoji?: string;
  /** Another way to say it, or what her book prints when Bonbon corrects it. */
  note?: string;
  spot: Spot;
}

/** The look of each chapter: an emoji and a colour of Bonbon's own. */
const LOOK: Record<number, [string, PaletteKey]> = {
  1: ['🏫', 'sky'],
  2: ['🏠', 'tangerine'],
  3: ['🍳', 'sunshine'],
  4: ['📦', 'plum'],
  5: ['🌦️', 'lagoon'],
  6: ['🛒', 'leaf'],
  7: ['👗', 'berry'],
  8: ['🏙️', 'grape'],
  9: ['🐄', 'leaf'],
  10: ['🍽️', 'tangerine'],
  11: ['🩺', 'sky'],
  12: ['💇', 'plum'],
  13: ['📮', 'berry'],
  14: ['⛽', 'sunshine'],
  15: ['👮', 'grape'],
  16: ['🚂', 'lagoon'],
  17: ['✈️', 'sky'],
  18: ['⚽', 'leaf'],
  19: ['🎭', 'plum'],
  20: ['🦁', 'sunshine'],
  21: ['🎪', 'berry'],
  22: ['🐠', 'lagoon'],
  23: ['🚀', 'grape'],
  24: ['🦕', 'tangerine'],
  25: ['🏰', 'plum'],
  26: ['🐭', 'sky'],
  27: ['🏃', 'leaf'],
  28: ['🎨', 'berry'],
  29: ['🌳', 'tangerine'],
  30: ['🔺', 'grape'],
  31: ['🔢', 'lagoon'],
  32: ['🗺️', 'sunshine'],
};

/** Version of the word list: words, boxes and order. Re-seeding and re-cutting follow it. */
export const IMAGIER_VERSION: string = meta.version;

export const IMAGIER_CHAPTERS: ImagierChapter[] = meta.chapters.map((c) => ({
  ...c,
  emoji: LOOK[c.num]?.[0] ?? '📖',
  color: LOOK[c.num]?.[1] ?? 'berry',
}));

export const CHAPTER_BY_NUM = new Map(IMAGIER_CHAPTERS.map((c) => [c.num, c]));

export const IMAGIER_WORD_COUNT = IMAGIER_CHAPTERS.reduce((n, c) => n + c.count, 0);

/** Every page of the book that has a chapter on it. */
export const IMAGIER_PAGES = [...new Set(IMAGIER_CHAPTERS.flatMap((c) => c.pages))].sort((a, b) => a - b);

export const pad2 = (n: number) => String(n).padStart(2, '0');

/** Theme (deck) of a chapter: "img-08". */
export const imagierDeckId = (num: number) => `img-${pad2(num)}`;

/** The chapter of a picture-dictionary theme, or 0. */
export function chapterOfDeck(deckId: string): number {
  const m = /^img-(\d\d)$/.exec(deckId);
  return m ? Number(m[1]) : 0;
}

export const isImagierDeck = (deckId: string) => chapterOfDeck(deckId) > 0;

interface RawWord {
  fr: string;
  en: string;
  k: ImagierKind;
  g?: 'm' | 'f' | 'mf';
  pl?: 1;
  e?: string;
  n?: string;
  p: number;
  b: Box;
  l: Box[];
}

/** Turns the generated chapters into words with stable ids. */
export function expandWords(chapters: { num: number; words: RawWord[] }[]): ImagierWord[] {
  const out: ImagierWord[] = [];
  for (const ch of chapters) {
    const seen = new Set<string>();
    for (const w of ch.words) {
      let id = `i${pad2(ch.num)}-${slugify(w.fr) || 'mot'}`;
      // the same word twice in a chapter (l'élève, the boy and the girl)
      for (let n = 2; seen.has(id); n++) id = `i${pad2(ch.num)}-${slugify(w.fr)}-${n}`;
      seen.add(id);
      out.push({
        id,
        chapter: ch.num,
        fr: w.fr,
        en: w.en,
        kind: w.k,
        ...(w.g ? { g: w.g } : {}),
        ...(w.pl ? { plural: true } : {}),
        ...(w.e ? { emoji: w.e } : {}),
        ...(w.n ? { note: w.n } : {}),
        spot: { p: w.p, b: w.b, l: w.l },
      });
    }
  }
  return out;
}

let wordsPromise: Promise<ImagierWord[]> | null = null;

/** Every word of the book (loaded on first use: it's the bigger file). */
export function loadImagierWords(): Promise<ImagierWord[]> {
  wordsPromise ??= import('./words.json').then((m) => {
    const data = (m.default ?? m) as unknown as { version: string; chapters: { num: number; words: RawWord[] }[] };
    return expandWords(data.chapters);
  });
  return wordsPromise;
}
